CalculateField join4_SpatialJoin1 KDB hitung_kdb(!d_kodszn!, !Shape_Area!) PYTHON3 "import arcpy

# cache total luas bangunan per d_kodszn
total_per_zona = None

def hitung_kdb(kode_zona, luas_bidang):
    global total_per_zona

    if kode_zona is None or luas_bidang in [None, 0]:
        return None

    # bangun dictionary sekali saja
    if total_per_zona is None:
        total_per_zona = {}

        fc = "join4_SpatialJoin1"   # ganti jika nama layer/tabel berbeda

        with arcpy.da.SearchCursor(fc, ["d_kodszn", "Shap_Ar"]) as cursor:
            for kod, luas_bangunan in cursor:
                if kod is None or luas_bangunan is None:
                    continue

                if kod not in total_per_zona:
                    total_per_zona[kod] = 0.0

                total_per_zona[kod] += float(luas_bangunan)

    total_bangunan = total_per_zona.get(kode_zona, 0.0)

    return round((total_bangunan / float(luas_bidang)) * 100, 2)" TEXT NO_ENFORCE_DOMAINS

CalculateField join4_SpatialJoin1 KDB hitung_kdb(!TARGET_FID!, !Shap_Ar!) PYTHON3 "import arcpy

cache_total = {}

def hitung_kdb(fid_bidang, luas_bidang):
    global cache_total

    if fid_bidang is None or luas_bidang in [None, 0]:
        return None

    # hitung total luas bangunan per bidang sekali saja
    if fid_bidang not in cache_total:
        total = 0.0
        fc = "join4_SpatialJoin1"   # ganti jika nama layer berbeda

        with arcpy.da.SearchCursor(fc, ["TARGET_FID", "Shape_Area"]) as cursor:
            for row in cursor:
                if row[0] == fid_bidang and row[1] is not None:
                    total += float(row[1])

        cache_total[fid_bidang] = total

    return round((cache_total[fid_bidang] / float(luas_bidang)) * 100, 2)" TEXT NO_ENFORCE_DOMAINS

