CalculateField Join_Full_Spatia_Spa_Project Keterangan cek(!d_kodszn!, !KDB_12!, !KLB_12!) PYTHON3 "def cek(zona, kdb, klb):
    if zona is None or kdb is None or klb is None:
        return "DATA TIDAK LENGKAP"

    # Zona Perdagangan & SPU
    if zona in ["K1", "K-1", "K2", "K-2", "SPU1", "SPU-1", "SPU2", "SPU-2", "SPU3", "SPU-3"]:
        if kdb <= 70 and klb <= 2.1:
            return "SESUAI"
        else:
            return "TIDAK SESUAI"

    # Zona Perumahan
    elif zona in ["R1", "R-1", "R2", "R-2", "R3", "R-3"]:
        if kdb <= 80 and klb <= 2.4:
            return "SESUAI"
        else:
            return "TIDAK SESUAI"

    # Zona lain
    else:
        return "ZONA TIDAK TERDEFINISI"" TEXT NO_ENFORCE_DOMAINS

